from pathlib import Path
import base64
import gzip

ROOT = Path.cwd() / "perax-market-adapters/meteora-dlmm-runtime"
FILES = {
    "src/index.ts": "",
    "test/runtime.test.ts": "",
    "test/bigint-buffer.test.ts": "",
}

for relative, encoded in FILES.items():
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(encoded)))

print("Installed the tested Meteora DLMM runtime source and tests.")
